#include "TrafficPanel.hpp"
#include <QComboBox>
#include <QDoubleSpinBox>
#include <QFormLayout>
#include <QHeaderView>
#include <QLabel>
#include <QPushButton>
#include <QSignalBlocker>
#include <QTableWidget>
#include <QVBoxLayout>
#include <cmath>
using Json=nlohmann::json;
TrafficPanel::TrafficPanel(QWidget*parent):QWidget(parent){setObjectName("trafficPanel");auto*layout=new QVBoxLayout(this);auto*form=new QFormLayout;layout->addLayout(form);selected_=new QComboBox;selected_->setObjectName("trafficActor");form->addRow("Actor",selected_);
 auto number=[&](const char*key,const QString&name,double lo,double hi,double v){auto*s=new QDoubleSpinBox;s->setObjectName(key);s->setRange(lo,hi);s->setValue(v);form->addRow(name,s);return s;};gap_=number("spawnGap","Centre ahead (m)",5,500,45);side_=number("spawnSide","Lateral offset (m)",-50,50,0);speed_=number("actorSpeed","Target speed (km/h)",0,216,36);
 auto button=[&](const char*key,const QString&text,auto callback){auto*b=new QPushButton(text);b->setObjectName(key);form->addRow(b);connect(b,&QPushButton::clicked,this,callback);};
 button("addTrafficCar","Add car ahead",[this]{command("add",true);});button("updateTrafficSpeed","Apply actor speed",[this]{command("update",false);});button("moveTrafficCar","Reposition selected car",[this]{command("update",true);});button("removeTrafficCar","Remove selected car",[this]{command("remove",false);});
 limit_=number("followingLimit","Cruise cap (km/h)",0,160,72);time_=number("followingTime","Time gap (s)",.5,4,1.5);standstill_=number("followingGap","Standstill gap (m)",2,25,7);gain_=number("followingGain","Gap gain (1/s)",.1,1,.45);gain_->setDecimals(2);
 button("enableFollowing","Apply adaptive following",[this]{if(!request||state_.empty())return;bool controller=false;for(const auto&e:state_.at("ecus"))if(e.at("definition").at("variables").contains("following_target_kph"))controller=true;if(!controller||!state_.at("controls").contains("following_time_s")){feedback_->setText("Load the Interactive traffic project for adjustable following.");return;}request({{"action","controls"},{"values",{{"assist_enabled",1},{"aeb_enabled",1},{"target_speed",limit_->value()},{"following_time_s",time_->value()},{"following_gap_m",standstill_->value()},{"following_gain",gain_->value()}}}},[this](const Json&){followingDirty_=false;setSnapshot(state_);feedback_->setText("Adaptive following enabled. Select D and Run; keep manual brake released.");});});
 following_=new QLabel;following_->setWordWrap(true);following_->setObjectName("followingMonitor");layout->addWidget(following_);
 for(auto*spin:{limit_,time_,standstill_,gain_})connect(spin,&QDoubleSpinBox::valueChanged,this,[this]{followingDirty_=true;});
 feedback_=new QLabel("Actors follow straight paths; speed changes use bounded acceleration. Enable adaptive cruise for ECU-controlled following.");feedback_->setWordWrap(true);layout->addWidget(feedback_);table_=new QTableWidget(0,4);table_->setHorizontalHeaderLabels({"ID","X m","Y m","km/h"});table_->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);table_->setEditTriggers(QAbstractItemView::NoEditTriggers);table_->setMinimumHeight(160);layout->addWidget(table_);
}
void TrafficPanel::setSnapshot(const Json&s){
 if(state_.empty()||state_.value("epoch",uint64_t(0))!=s.value("epoch",uint64_t(0)))followingDirty_=false;
 state_=s;
 if(!followingDirty_){const auto&c=s.at("controls");QSignalBlocker a(limit_),b(time_),d(standstill_),e(gain_);limit_->setValue(c.value("target_speed",72.0));time_->setValue(c.value("following_time_s",1.5));standstill_->setValue(c.value("following_gap_m",7.0));gain_->setValue(c.value("following_gain",.45));}
const auto&w=s.at("world");QString status=QString("Lead: %1\nGap %2 m · closing %3 m/s\nAdaptive %4").arg(QString::fromStdString(s.value("traffic",Json::object()).value("lead_id",std::string("none")))).arg(w.value("lead_distance",600.0),0,'f',1).arg(w.value("closing_speed",0.0),0,'f',1).arg(s.at("controls").value("assist_enabled",0.0)!=0?"ON":"OFF");for(const auto&e:s.at("ecus"))if(e.at("name")=="ADAS ECU"&&e.at("values").contains("following_target_kph"))status+=QString("\nECU target %1 km/h · brake %2 %").arg(e.at("values").at("following_target_kph").get<double>(),0,'f',1).arg(e.at("values").at("following_brake").get<double>()*100,0,'f',1);status+=QString("\nApplied cap %1 km/h · headway %2 s").arg(s.at("controls").value("target_speed",0.0),0,'f',0).arg(s.at("controls").value("following_time_s",0.0),0,'f',1);following_->setText(status);auto actors=s.value("traffic",Json::object()).value("actors",Json::array());QStringList names;for(const auto&a:actors)names<<QString::fromStdString(a.at("id"));QStringList old;for(int i=0;i<selected_->count();++i)old<<selected_->itemText(i);if(old!=names){auto name=selected_->currentText();selected_->clear();selected_->addItems(names);if(names.contains(name))selected_->setCurrentText(name);}table_->setRowCount(actors.size());int row=0;for(const auto&a:actors){QStringList cells={QString::fromStdString(a.at("id")),QString::number(a.at("x").get<double>(),'f',1),QString::number(a.at("y").get<double>(),'f',1),QString::number(a.at("speed").get<double>()*3.6,'f',1)};for(int col=0;col<4;++col){if(!table_->item(row,col))table_->setItem(row,col,new QTableWidgetItem);table_->item(row,col)->setText(cells[col]);}++row;}}
void TrafficPanel::command(const std::string&operation,bool reposition){if(!request||state_.empty())return;auto id=selected_->currentText().toStdString();Json actor={{"target_speed",speed_->value()/3.6}};if(operation=="add"){auto exists=[&](const std::string&name){for(const auto&a:state_.value("traffic",Json::object()).value("actors",Json::array()))if(a.at("id")==name)return true;return false;};do{id="car-"+std::to_string(nextId_++);}while(exists(id));actor["speed"]=speed_->value()/3.6;}
 if(reposition){const auto&w=state_.at("world");double yaw=w.value("heading",0.0);actor["x"]=w.value("x",w.value("position",0.0))+gap_->value()*std::cos(yaw)-side_->value()*std::sin(yaw);actor["y"]=w.value("y",0.0)+gap_->value()*std::sin(yaw)+side_->value()*std::cos(yaw);actor["yaw"]=yaw;}
 if(id.empty()){feedback_->setText("Select an actor first.");return;}request({{"action","traffic_actor"},{"operation",operation},{"id",id},{"actor",actor}},[this,id](const Json&){feedback_->setText("Actor updated: "+QString::fromStdString(id));selected_->setCurrentText(QString::fromStdString(id));});}
